from django.db import IntegrityError, models, transaction

class Membership(models.Model):
    user = models.ForeignKey("auth.User", on_delete=models.CASCADE)
    team = models.ForeignKey("Team", on_delete=models.CASCADE)
    role = models.CharField(max_length=20, default="member")
    is_active = models.BooleanField(default=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["user", "team"],
                condition=models.Q(is_active=True),
                name="unique_active_membership",
            ),
            models.CheckConstraint(
                condition=models.Q(role__in=["owner", "admin", "member"]),
                name="valid_membership_role",
            ),
        ]

def add_membership(user, team):
    try:
        with transaction.atomic():
            return Membership.objects.create(user=user, team=team)
    except IntegrityError as exc:
        raise ValueError("This user is already an active member.") from exc
